#define main legacy_main
#include "tensorT-cuda/main.cu"
#undef main
#include <vector>
#include <cmath>
int main(){const int A=5,B=7,C=11,D=3,E=4,F=5,n=A*B*C*D*E*F;std::vector<double>x(n),want(n),out(n);for(int i=0;i<n;i++)x[i]=i-100;for(int f=0;f<F;f++)for(int e=0;e<E;e++)for(int d=0;d<D;d++)for(int c=0;c<C;c++)for(int b=0;b<B;b++)for(int a=0;a<A;a++){int i=a+A*(b+B*(c+C*(d+D*(e+E*f))));int j=b+B*(c+C*(d+D*(f+F*(a+A*e))));want[j]=x[i];}int si[]={D,E,F},so[]={B,C,A},sti[]={B*C,B*C*D*F*A,B*C*D},stl[]={A,A*B,1},stg[]={1,B,B*C*D*F};float ri[]={1.f/D,1.f/E,1.f/F},ro[]={1.f/B,1.f/C,1.f/A};int *dsi,*dso,*dsti,*dstl,*dstg;float*dri,*dro;double*dx,*dy;auto ci=[](int*h,int**d){cudaMalloc(d,12);cudaMemcpy(*d,h,12,cudaMemcpyHostToDevice);};auto cf=[](float*h,float**d){cudaMalloc(d,12);cudaMemcpy(*d,h,12,cudaMemcpyHostToDevice);};ci(si,&dsi);ci(so,&dso);ci(sti,&dsti);ci(stl,&dstl);ci(stg,&dstg);cf(ri,&dri);cf(ro,&dro);cudaMalloc(&dx,n*8);cudaMalloc(&dy,n*8);cudaMemcpy(dx,x.data(),n*8,cudaMemcpyHostToDevice);auto run=[&](){tensor_transpose<<<60,256>>>(3,3,60,385,dsi,dso,dri,dro,dsti,dstl,dstg,dx,dy);};run();if(cudaDeviceSynchronize()!=cudaSuccess)return 2;for(int trial=1;trial<=5;trial++){auto t=std::chrono::steady_clock::now();for(int k=0;k<10;k++)run();if(cudaDeviceSynchronize()!=cudaSuccess)return 2;double seconds=std::chrono::duration<double>(std::chrono::steady_clock::now()-t).count()/10;cudaMemcpy(out.data(),dy,n*8,cudaMemcpyDeviceToHost);double err=0;bool ok=true;for(int i=0;i<n;i++){err=std::max(err,fabs(out[i]-want[i]));ok=ok&&std::isfinite(out[i])&&out[i]==want[i];}char path[64];snprintf(path,sizeof(path),"trial_%d.bin",trial);FILE*f=fopen(path,"wb");fwrite(out.data(),8,n,f);fclose(f);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.15g,\"correct\":%s,\"checked_values\":%d,\"max_abs_error\":%.15g,\"timing_region\":\"mean_ten_bulk_kernel_launches\",\"jit_excluded\":true,\"internal_repeats\":10,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float64\",\"count\":%d,\"byte_order\":\"little\"}}\n",trial,seconds,ok?"true":"false",n,err,path,n);if(!ok)return 1;}cudaFree(dx);cudaFree(dy);cudaFree(dsi);cudaFree(dso);cudaFree(dsti);cudaFree(dstl);cudaFree(dstg);cudaFree(dri);cudaFree(dro);}
